ALTER TABLE tickets ADD COLUMN email TEXT NOT NULL DEFAULT '';
ALTER TABLE tickets ADD COLUMN revision INTEGER NOT NULL DEFAULT 0;
ALTER TABLE tickets ADD COLUMN last_event_id TEXT NOT NULL DEFAULT '';
CREATE TABLE mail_threads(ticket_id TEXT PRIMARY KEY REFERENCES tickets(id),visitor_key TEXT NOT NULL UNIQUE,admin_key TEXT NOT NULL UNIQUE,access_token TEXT NOT NULL DEFAULT '',suppressed INTEGER NOT NULL DEFAULT 0,visitor_message_id TEXT NOT NULL DEFAULT '',admin_message_id TEXT NOT NULL DEFAULT '');
CREATE TABLE ticket_events(id TEXT PRIMARY KEY,ticket_id TEXT NOT NULL REFERENCES tickets(id),kind TEXT NOT NULL,body TEXT NOT NULL DEFAULT '',status TEXT NOT NULL,previous_status TEXT NOT NULL,role TEXT NOT NULL,source TEXT NOT NULL DEFAULT 'web',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notification_jobs(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES ticket_events(id),channel TEXT NOT NULL,audience TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,provider_id TEXT NOT NULL DEFAULT '',error TEXT NOT NULL DEFAULT '',next_attempt INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_notification_jobs_due ON notification_jobs(status,next_attempt);
CREATE TABLE mail_inbound(id TEXT PRIMARY KEY,email_id TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,error TEXT NOT NULL DEFAULT '',next_attempt INTEGER NOT NULL DEFAULT 0,ticket_id TEXT,message_id TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE mail_webhooks(id TEXT PRIMARY KEY,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS mail_references(message_id TEXT PRIMARY KEY,ticket_id TEXT NOT NULL REFERENCES tickets(id),audience TEXT NOT NULL);
